{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C55","C56","C61","C63"],
  "contradictory_card_ids": ["C10","C22","C06","C11","C05","C08","C15","C16","C14","C23","C50","C47","C45","C42","C51","C48"],
  "prediction_basis_card_ids": ["C55","C56","C61","C63"],
  "claims": [
    {
      "claim": "The query is a fully ionized dianionic bis-acid (logD -3.24, TPSA 126.8, no basic amine), unlike the zwitterionic mono-acid quinolones whose oral F is high (ofloxacin/levofloxacin ~100%, C10/C22/C06/C11) or moderate (norfloxacin 30-45%, C05/C08/C15/C16/C14/C23); those high-F records are low-transferability and do not outweigh the query's polarity.",
      "card_ids": ["C10","C22","C06","C11","C05","C08","C15","C16","C14","C23"]
    },
    {
      "claim": "Enalaprilat, a dicarboxylic acid, has measured low intestinal permeability (rat jejunum P_eff 0.013 ± 0.009 ×10^-4 cm/s, C56; Papp 4.61 ± 0.78 ×10^-6 cm/s in nanoparticle dispersion, C55), providing a transferable pattern for poor absorption of highly polar dicarboxylic acids.",
      "card_ids": ["C55","C56"]
    },
    {
      "claim": "L5 efflux records show an anionic flavone (7,8-DHF) is subject to P-gp/MRP2-mediated efflux in Caco-2 (C61, C63), supporting possible additional presystemic loss for anionic compounds, though chemotype transfer is limited.",
      "card_ids": ["C61","C63"]
    },
    {
      "claim": "L4 fraction-absorbed records report near-complete oral absorption for ofloxacin, levofloxacin, pefloxacin, enoxacin, and fleroxacin (C50, C47, C45, C42, C51, C48), but these analogs have a single carboxyl and a basic amine, so transfer to the dianionic bis-acid query is limited.",
      "card_ids": ["C50","C47","C45","C42","C51","C48"]
    },
    {
      "claim": "L6 hepatic-clearance records show measurable hepatic metabolism for some carboxylic-acid/quinolone compounds (enrofloxacin HLM CLint 16.09 µL/min/mg and t1/2 43.1 min, C71/C70; DMXAA UGT glucuronidation, C66/C69/C73/C76), but none is the query or a close dianionic bis-acid, so this is only weak mechanistic support for presystemic loss.",
      "card_ids": ["C71","C70","C66","C69","C73","C76"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C65","C66","C67","C68","C69","C70","C71","C72","C73","C74","C75","C76"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability or permeability exists for the exact query molecule.",
    "No query-specific hepatic clearance or metabolic stability data; L6 records are from enrofloxacin, DMXAA, repaglinide, and amiodarone.",
    "No query-specific transporter/efflux data; enalaprilat and flavone records are different chemotypes.",
    "High-F quinolone analogs differ by having a basic amine and single carboxyl, limiting transfer to the dianionic bis-acid query.",
    "Food effects, formulation, and active transport for the query are unverified."
  ],
  "decision_summary": "L6 hepatic-clearance records are mechanistically supportive of possible presystemic loss but are low-transferability and do not change the L5 conclusion. The query's dianionic, fully ionized bis-acid character, supported by enalaprilat's low dicarboxylic-acid permeability and the unfavorable physicochemical prior, supports F < 20%; prediction remains low with moderate confidence."
}

